mapper.select:
SELECT ANALYSIS_ID AS "analysisId", ANALYSIS_NO AS "analysisNo", ANALYSIS_NAME AS "analysisName", ANALYSIS_PERIOD AS "analysisPeriod", BUDGET_ID AS "budgetId", BUDGET_AMOUNT AS "budgetAmount", ACTUAL_AMOUNT AS "actualAmount", VARIANCE_AMOUNT AS "varianceAmount", VARIANCE_RATE AS "varianceRate", VARIANCE_TYPE AS "varianceType", ANALYST_NAME AS "analystName", ANALYSIS_DATE AS "analysisDate", CREATE_TIME AS "createTime" FROM TBL_VARIANCE_ANALYSIS WHERE BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND ANALYSIS_PERIOD = #{analysisPeriod}
AND BUDGET_ID = #{budgetId}
AND VARIANCE_TYPE = #{varianceType}
ORDER BY ANALYSIS_DATE DESC, CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_VARIANCE_ANALYSIS
WHERE BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND ANALYSIS_PERIOD = #{analysisPeriod}


      AND BUDGET_ID = #{budgetId}


      AND VARIANCE_TYPE = #{varianceType}

SELECT
    COUNT(1) AS "totalCount",
    SUM(VARIANCE_AMOUNT) AS "totalVariance",
    SUM(CASE WHEN VARIANCE_TYPE = 'FAVORABLE' THEN VARIANCE_AMOUNT ELSE 0 END) AS "favorableVariance",
    SUM(CASE WHEN VARIANCE_TYPE = 'UNFAVORABLE' THEN VARIANCE_AMOUNT ELSE 0 END) AS "unfavorableVariance",
    AVG(VARIANCE_RATE) AS "avgVarianceRate"
FROM TBL_VARIANCE_ANALYSIS
WHERE ANALYSIS_PERIOD = #{analysisPeriod}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

SELECT pc.COSTING_PERIOD AS "period", pc.COST_CENTER_ID AS "costCenterId", pc.COST_CENTER_NAME AS "costCenterName", pc.PRODUCT_ID AS "productId", pc.PRODUCT_CODE AS "productCode", pc.PRODUCT_NAME AS "productName", pc.PRODUCT_TYPE AS "productType", pc.BUDGET_COST AS "budgetCost", pc.STANDARD_COST AS "standardCost", pc.TOTAL_COST AS "actualCost", pc.DIRECT_MATERIAL AS "actualMaterial", pc.DIRECT_LABOR AS "actualLabor", pc.MANUFACTURING_OVERHEAD AS "actualOverhead", pc.PRODUCTION_QUANTITY AS "productionQuantity" FROM T_PRODUCT_COST pc WHERE COALESCE(pc.IS_DELETED, 0) = 0 AND pc.TOTAL_COST IS NOT NULL
AND pc.COSTING_PERIOD >= #{startPeriod}
AND pc.COSTING_PERIOD <= #{endPeriod}
AND pc.COST_CENTER_ID IN
#{cid}
AND pc.PRODUCT_TYPE IN
1 2 3 4 5 -1
ORDER BY pc.COSTING_PERIOD, pc.COST_CENTER_ID, pc.PRODUCT_ID
